// th15_s6_w03: TH15 Stage 6 MainSub02 wave (st06.ecl.txt:627-672).
// Four rounds x 32 Phantom03, 3 frames apart, 180 frames between rounds.
// Chapter entry/state and -9905 gating are omitted per the TH15 policy.

const TIME_LIMIT: int = 2124;
const OPENING_BUFFER: int = 120;
const PHANTOM_HP: int = 120;

// Phantom03 (st06.ecl.txt:1101-1124) and Phantom03_at (1126-1156).
// The source passes no inherited I/F slots that these subs read.
async sub phantom() {
    set_invuln(65535);
    set_hurtbox(14fx);   // setHurtbox(28,28): circular branch 28 * 0.5
    set_hitbox(8fx);     // setHitbox(16,16): circular branch 16 * 0.5

    var relx: fx = 0fx;
    var rely: fx = 0fx;

    // moveVel(pi/2,4) then moveVelTime(30,0,pi/2,0): ABS speed 4 -> 0, downward.
    for k in 1..31 {
        var v: fx = 4fx * ((30 - k) as fx) / 30fx;
        move_vel_xy(0, 0fx, v, EASE_LINEAR);
        wait(1);
    }

    // Source frame 30: moveVel(ANGLE_PLAYER,0) freezes ABS at the self-player
    // direction; moveSpeedTime(240,1,2.0) then ramps speed 0 -> 2 (t^2).
    var ang: angle = aim_player();

    // moveCircleRel(RANDRAD, 1deg/frame, -pi/16 px, 0) and
    // moveCircleRelTime(80,0,keep,16,0): REL: centre snapshotted at (0,0),
    // radius -0.19635 -> 16 px over 80 ticks, phase 1 deg/frame.
    var theta: angle = (rand(65536) - 32768) as angle;
    var r0: fx = -0.19635fx;
    relx = r0 * cos(theta);
    rely = r0 * sin(theta);

    spawn phantom_at();

    // ABS + REL per-frame composition, armed one movement tick ahead.
    var k2: int = 0;
    loop {
        k2 = k2 + 1;
        var rr: fx = 16fx;
        if k2 <= 80 {
            var rf: fx = (k2 as fx) / 80fx;
            rr = r0 + (16fx - r0) * rf;
        }
        var spd: fx = 2fx;
        if k2 <= 240 {
            var u: fx = (k2 as fx) / 240fx;
            spd = 2fx * u * u;
        }
        theta = theta + 1deg;
        var nrx: fx = rr * cos(theta);
        var nry: fx = rr * sin(theta);
        move_vel_xy(0, spd * cos(ang) + (nrx - relx),
                       spd * sin(ang) + (nry - rely), EASE_LINEAR);
        relx = nrx;
        rely = nry;
        wait(1);
    }
}

// Phantom03_at: etAim(0,1) fixed-direction 1-way fan, etSprite(0,12,6),
// etSpeed s0=2.5; each shot re-reads RANDF2 for etAngle(pi/2 +- 20deg).
// diffI gives shots/interval E/N/H/L = 3/90, 10/30, 20/20, 30/10.
async sub phantom_at() {
    var n: int = 30;
    var gap: int = 10;
    var rank: int = global(GVAR_RANK);
    if rank == 0 { n = 3; gap = 90; }
    else if rank == 1 { n = 10; gap = 30; }
    else if rank == 2 { n = 20; gap = 20; }
    for i in 0..n {
        var u: fx = ((rand(65536) - 32768) as fx) / 32768;
        var off: int = (3641fx * u) as int;   // 20 deg in BAM
        _ = fire(TH15_ARROWHEAD, 6, $self_x, $self_y, 2.5fx,
                 90deg + (off as angle), none, none);
        wait(gap);
    }
}

// enmCreate: parent FINAL + (x + RANDF2*16, 64 + RANDF2*32), hp 120.
// Drops/presentation omitted; ranks and the two random draws stay in order.
sub spawn_one(x: fx) {
    var ux: fx = ((rand(65536) - 32768) as fx) / 32768;
    var uy: fx = ((rand(65536) - 32768) as fx) / 32768;
    _ = spawn_enemy(x + ux * 16fx, 64fx + uy * 32fx, PHANTOM_HP, 0, 0, 0, phantom);
}

// MainSub02 schedule: A starts at -160 and keeps its post-loop value, so
// rounds start at -160, 160, -160, 160. Source tail wait(260).
async sub pattern() {
    wait(OPENING_BUFFER);
    var ax: fx = -160fx;
    for i1 in 0..32 { spawn_one(ax); ax = ax + 10fx; wait(3); }
    wait(180);
    for i2 in 0..32 { spawn_one(ax); ax = ax - 10fx; wait(3); }
    wait(180);
    for i3 in 0..32 { spawn_one(ax); ax = ax + 10fx; wait(3); }
    wait(180);
    for i4 in 0..32 { spawn_one(ax); ax = ax - 10fx; wait(3); }
    wait(260);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

